import numpy as np, wfdb, json, os
from scipy.signal import butter, filtfilt, medfilt, find_peaks

FS=500
def load(eid, d='/tmp/ecg'):
    r=wfdb.rdrecord(os.path.join(d,str(eid)))
    sig=np.asarray(r.p_signal,dtype=float)  # (N,12) mV
    names=[n.strip() for n in r.sig_name]
    # fill nans
    for i in range(sig.shape[1]):
        c=sig[:,i]
        if np.isnan(c).any():
            idx=np.arange(len(c)); m=~np.isnan(c)
            if m.sum()<10: c[:]=0
            else: c[:]=np.interp(idx,idx[m],c[m])
    return sig,names,r

def bp(x,lo,hi,fs=FS,order=3):
    b,a=butter(order,[lo/(fs/2),hi/(fs/2)],btype='band')
    return filtfilt(b,a,x,axis=0)

def baseline_remove(x,fs=FS):
    # median filter baseline
    k1=int(0.2*fs)|1; k2=int(0.6*fs)|1
    out=np.empty_like(x)
    for i in range(x.shape[1]):
        b=medfilt(medfilt(x[:,i],k1),k2)
        out[:,i]=x[:,i]-b
    return out

def notch_lp(x,hi=40,fs=FS):
    b,a=butter(4,hi/(fs/2),btype='low')
    return filtfilt(b,a,x,axis=0)
